/**
 * Bundles jszip.min.js and epub.min.js from node_modules into a single
 * TypeScript file that can be imported by epubReaderHtml.ts.
 * Run once: node scripts/bundle-epub-libs.js
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const jszip = fs.readFileSync(path.join(root, 'node_modules/jszip/dist/jszip.min.js'), 'utf8');
const epub  = fs.readFileSync(path.join(root, 'node_modules/epubjs/dist/epub.min.js'),  'utf8');

// Escape backticks and ${} so the code is safe inside a template literal
function escapeForTemplate(code) {
  return code
    .replace(/\\/g, '\\\\')
    .replace(/`/g, '\\`')
    .replace(/\$\{/g, '\\${');
}

const out = `// AUTO-GENERATED by scripts/bundle-epub-libs.js – do not edit by hand.
// Re-run: node scripts/bundle-epub-libs.js

export const JSZIP_JS = \`${escapeForTemplate(jszip)}\`;
export const EPUB_JS  = \`${escapeForTemplate(epub)}\`;
`;

const outPath = path.join(root, 'src/utils/epubLibs.ts');
fs.writeFileSync(outPath, out, 'utf8');
console.log('Written', outPath, '(' + Math.round(out.length / 1024) + ' KB)');
